package io.tornado.api;
import io.tornado.optimization.*;import io.tornado.persistence.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/reports/strategy-profiles")public class StrategyProfileController{private final StrategyHorizonProfileRepository profiles;private final ProfileResearchService research;public StrategyProfileController(StrategyHorizonProfileRepository p,ProfileResearchService r){profiles=p;research=r;}
 @GetMapping public List<ProfileDto>list(@RequestParam(defaultValue="true")boolean active,@RequestParam(required=false)String coin,@RequestParam(required=false)Long horizon){List<StrategyHorizonProfile>rows=active?profiles.findByActiveTrueOrderByPredictionHorizonSecondsAscStrategyCodeAsc():profiles.findAllByOrderBySelectedAtDesc();return rows.stream().filter(p->horizon==null||p.getPredictionHorizonSeconds()==ReportService.requireSupportedHorizon(horizon)).filter(p->coin==null||p.getCoinSymbol()==null||p.getCoinSymbol().equalsIgnoreCase(coin)).map(ProfileDto::of).toList();}
 @PostMapping("/research")public ProfileResearchService.ResearchResult research(@Valid @RequestBody ResearchRequest request){Instant to=request.to()==null?Instant.now():request.to();return research.research(request.scope(),request.coin(),request.strategyCode(),request.horizon(),request.from(),to);}
 public record ResearchRequest(@NotNull ProfileScope scope,String coin,@NotBlank String strategyCode,@Positive long horizon,@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant from,@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant to){}
 public record ProfileDto(long id,String strategyCode,int strategyVersion,long predictionHorizonSeconds,String analysisTimeframe,String parameterKey,int profileVersion,ProfileScope scope,String coin,ProfileSelectionSource source,long trainingSamples,long validationSamples,long testSamples,double targetHitRate,double directionalAccuracy,double wilsonTargetScore,double wilsonDirectionalScore,double profitableTradeRate,double averageMarketReturn,double medianMarketReturn,double netPnlPercent,double maximumDrawdownPercent,int walkForwardWindows,int walkForwardPositiveWindows,double walkForwardConsistency,double selectionScore,boolean active,Instant selectedAt,Instant supersededAt,String reason){static ProfileDto of(StrategyHorizonProfile p){return new ProfileDto(p.getId(),p.getStrategyCode(),p.getStrategyVersion(),p.getPredictionHorizonSeconds(),p.getAnalysisTimeframe(),p.getParameterKey(),p.getProfileVersion(),p.getProfileScope(),p.getCoinSymbol(),p.getSelectionSource(),p.getTrainingSamples(),p.getValidationSamples(),p.getTestSamples(),p.getTargetHitRate(),p.getDirectionalAccuracy(),p.getWilsonTargetScore(),p.getWilsonDirectionalScore(),p.getProfitableTradeRate(),p.getAverageMarketReturn(),p.getMedianMarketReturn(),p.getNetPnlPercent(),p.getMaximumDrawdownPercent(),p.getWalkForwardWindows(),p.getWalkForwardPositiveWindows(),p.getWalkForwardConsistency(),p.getSelectionScore(),p.isActive(),p.getSelectedAt(),p.getSupersededAt(),p.getReplacementReason());}}
}
